<?php
if(!defined('ABSPATH')){exit(1);}$f=get_option('cvt_exceptions_fixture');global $wpdb;$events=$wpdb->prefix.'cvd_order_events';$assert=static function($ok,$message){if(!$ok){throw new RuntimeException($message);}};
$incident=wc_get_order(absint($f['incident']));$assert('handed_over'===$incident->get_meta('_cvd_delivery_status',true),'incidencia perdió etapa');$assert('no'===$incident->get_meta('_cvd_delivery_incident_active',true),'incidencia no resuelta');$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$events} WHERE order_id=%d AND event_type='incident.opened'",$incident->get_id())),'apertura duplicada');$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$events} WHERE order_id=%d AND event_type='incident.resolved'",$incident->get_id())),'resolución duplicada');
$legacy=wc_get_order(absint($f['legacy']));$assert('incident'===$legacy->get_meta('_cvd_delivery_status',true),'legacy truncado inventó etapa');
foreach(array('before','offered','assigned','refund','failed','race')as$key){$o=wc_get_order(absint($f[$key]));$assert('cancelled'===$o->get_meta('_cvd_operation_status',true),$key.' operation no cancelada');$assert('cancelled'===$o->get_meta('_cvd_delivery_status',true),$key.' delivery no cancelada');$assert('cancelled'===$o->get_meta('_cvd_commission_status',true),$key.' comisión no cancelada');$assert('cancelled'===$o->get_meta('_cvd_messenger_earning_status',true),$key.' earning no cancelado');$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$events} WHERE order_id=%d AND domain='operation' AND to_state='cancelled'",$o->get_id())),$key.' evento operation duplicado');$assert(1===(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$events} WHERE order_id=%d AND domain='delivery' AND to_state='cancelled'",$o->get_id())),$key.' evento delivery duplicado');}
$failed=wc_get_order(absint($f['failed']));$assert('failed'===$failed->get_status(),'Woo failed fue normalizado indebidamente');$refund=wc_get_order(absint($f['refund']));$assert('refunded'===$refund->get_status(),'refund perdió semántica WooCommerce');$race=wc_get_order(absint($f['race']));$receipts=(array)$race->get_meta('_cvd_transition_receipts',true);$assert(isset($receipts[hash('sha256','exceptions-race-cancel')]),'falta receipt carrera');echo "OK: excepciones 1C.4 verificadas en MariaDB.\n";
